/**
 * LA FICHA DEL PAÍS — lo único que cambia de un país a otro en el prompt.
 *
 * Nace del mapa del prompt de Chile (21-sep): 182 líneas locales en siete
 * variables. Cada campo se agrega cuando su variable se extrae del núcleo;
 * mientras no se use, es documentación de lo que viene.
 */
export type FichaPrompt = {
  pais: "cl" | "co" | "mx" | "pe"
  /** Documento tributario de la empresa (RUT, RUC, NIT, RFC). */
  documento: string
  /** Documento personal del administrador (RUT, DNI, cédula, CURP). */
  documentoAdmin: string
  /** Unidad de precio del catálogo (UF, S/, COP, MXN). */
  moneda: string
  /** Impuesto y su tasa (IVA 19, IGV 18…). */
  impuesto: string
  impuestoPct: number
  /** Unidad geográfica que se pregunta con reloj físico (comuna, distrito). */
  zona: string
  /** La misma unidad en mayúscula inicial (arranque de frase). */
  zonaCap: string
  zonaTz: string
  gentilicio: string
  /** VARIABLES DE PALABRA extraídas el 21-sep (segunda tanda): cada una es un
   *  fragmento chileno del núcleo que otro país reemplaza. */
  ejemploDudaLegal: string
  ejemploMonto: string
  ejemploDudaLegalCorto: string
  ejemploDudaLegalTema: string
  ejemploMontoApp: string
  advertenciaRelojExterno: string
  vendedoraLocal: string
  whatsappLocal: string
  reglaTuteo: string
  equipoComercialLocal: string
  tuLocal: string
  registroNeutro: string
  gentilicioPl: string
  tramosInstalacion: string
  extrasFueraMenu: string
  fueraZonaCentral: string
  duenoRegistroFormal: string
  extrasReactivos: string
  notaNocturna: string
  argTurnosConfig: string
  argRespaldoNormativo: string
  metodosRelojIds: string
  aclaracionHuellero: string
  /** "LA COMUNA JAMÁS SE ASUME (…): ni Región Metropolitana ni ninguna otra por defecto" en Chile. */
  zonaNoSeAsume: string
  /** Ejemplo del caso 17-jul de presupuesto que alcanza, en la moneda del país. */
  ejemploPresupuesto: string
  /** Datos del cierre y regla del nombre de la empresa: Chile resuelve la razón social por SII desde el RUT; Perú la pide. */
  reglaNombreEmpresa: string
  reglaNombreEmpresaPaso1: string
  prohibidoNombreEmpresa: string
  datosCierreParen: string
  reglaNombreEmpresaCierre: string
  pedirDeMas: string
  daDatosCierre: string
  cierreConFormulario: string
  peticionNombraAmbos: string
  datosCierre: string
  /**
   * BLOQUES LOCALES — texto entero por país, no palabras: estilo local,
   * herramientas disponibles (los nombres cambian por país), venta del reloj
   * (equipo y devolución), bloque legal, instalación con tarifas por zona y
   * agenda (Perú no la tiene). Se inyectan en el mismo lugar del núcleo con
   * `${f.bloques.x}`. Son strings PLANOS (ya resueltos), no templates.
   */
  bloques: {
    estiloLocal: string
    tools: string
    reloj: string
    legal: string
    instalacion: string
    agenda: string
    condicionesArriendo: string
    objecionesHardware: string
    equiposLocales: string
  }
}

